<?php require '../config/auth.php';require '../config/database.php';wajibPelanggan();$id=$_SESSION['user_id'];$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$q=$pdo->prepare('UPDATE users SET nama=?,username=?,hp=?,password=? WHERE id=?');$q->execute([$_POST['nama'],$_POST['username'],$_POST['hp'],$_POST['password'],$id]);$_SESSION['nama']=$_POST['nama'];header('Location: profil.php?success=profile_updated');exit;}$q=$pdo->prepare('SELECT * FROM users WHERE id=?');$q->execute([$id]);$u=$q->fetch(PDO::FETCH_ASSOC);$q=$pdo->prepare('SELECT * FROM transactions WHERE user_id=? ORDER BY id DESC');$q->execute([$id]);$ts=$q->fetchAll(PDO::FETCH_ASSOC);?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Profil</title><link rel="stylesheet" href="../assets/css/style.css"><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script><script src="../assets/js/sweetalert.js"></script></head><body><header><a class="brand" href="../index.php">Style<span>Kita</span></a><nav><a href="index.php">Produk</a><a href="keranjang.php">Keranjang</a><a href="profil.php">Profil</a></nav><a href="../logout.php">Logout</a></header><section class="section"><h1>Profil Saya</h1><form class="profile-form" method="post" data-swal-loading="Menyimpan profil..."><input name="nama" value="<?=$u['nama']?>" placeholder="Nama"><input name="username" value="<?=$u['username']?>" placeholder="Username"><input name="hp" value="<?=$u['hp']?>" placeholder="No. HP"><input name="password" value="<?=$u['password']?>" placeholder="Password"><button class="btn">Simpan</button></form><h2>Riwayat Transaksi</h2><div class="table"><div class="tr head"><b>ID</b><b>Total</b><b>Status</b><b>Aksi</b></div><?php foreach($ts as $t):?><div class="tr"><span>#<?=$t['id']?></span><span>Rp <?=number_format($t['total'],0,',','.')?></span><span><?=$t['status']?></span><a href="invoice.php?id=<?=$t['id']?>">Cetak Invoice</a></div><?php endforeach;?></div></section></body></html>
